import type { ShapeName } from '../types'
import arrowSvg from './arrow.svg?raw'
import pointerSvg from './pointer.svg?raw'
import handSvg from './hand.svg?raw'

/** Inlined SVG markup for each bundled shape. */
export const SHAPE_SVGS: Record<ShapeName, string> = {
  arrow: arrowSvg,
  pointer: pointerSvg,
  hand: handSvg,
}

/**
 * Multiplier applied to `strokeWidth` so strokes look similar across viewBoxes.
 * Hand uses a 256×256 box vs ~24 for arrow/pointer.
 */
export const SHAPE_STROKE_SCALE: Record<ShapeName, number> = {
  arrow: 1,
  pointer: 1,
  hand: 256 / 24,
}

/**
 * Hotspots as fractions of each shape’s viewBox (tip of the cursor).
 * Arrow viewBox: -1 6 13.5 20.5 — tip ≈ (0.9, 8.1), box tight to glyph
 * Pointer viewBox: 0 0 24 24 — tip ≈ (4.5, 3.1) after flip
 * Hand viewBox: 0 0 256 256 — index tip ≈ (107.7, 16) after midline
 */
export const SHAPE_HOTSPOTS: Record<ShapeName, { x: number; y: number }> = {
  arrow: { x: 0.14, y: 0.1 },
  pointer: { x: 0.19, y: 0.13 },
  hand: { x: 0.42, y: 0.06 },
}

/**
 * Tip offset from pointing **up** at CSS rotate(0), in degrees.
 * Hand index points up → 0. Arrow/pointer tips point up-left → -45.
 * Used by dangling motion so the tip aims along travel.
 */
export const SHAPE_DEFAULT_ANGLES: Record<ShapeName, number> = {
  arrow: -45,
  pointer: -45,
  hand: 0,
}

import type { MotionFrame, Point } from '../types'

export interface CubicBezierPath {
  p0: Point
  p1: Point
  p2: Point
  p3: Point
}

export interface SamplePathOptions {
  /** When false, skip derivative + atan2 (dangling with locked travel heading). */
  needHeading?: boolean
  /** Reuse this object instead of allocating a new MotionFrame. */
  out?: MotionFrame
}

export interface AnimateAlongOptions {
  duration: number
  /** Called every frame with sample data. */
  onFrame: (frame: MotionFrame) => void
  /** Easing function mapping linear t ∈ [0,1] → eased t. Default ease-in-out. */
  ease?: (t: number) => number
  needHeading?: boolean
  /** Optional now() for tests. */
  now?: () => number
  /** Optional rAF / cancel for tests. */
  raf?: (cb: FrameRequestCallback) => number
  caf?: (id: number) => void
}

export interface AnimateHandle {
  cancel: () => void
  finished: Promise<void>
}

function clamp(n: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, n))
}

/** Smoothstep-ish ease-in-out. */
export function easeInOutCubic(t: number): number {
  const x = clamp(t, 0, 1)
  return x < 0.5 ? 4 * x * x * x : 1 - (-2 * x + 2) ** 3 / 2
}

function distance(a: Point, b: Point): number {
  const dx = b.x - a.x
  const dy = b.y - a.y
  return Math.hypot(dx, dy)
}

function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t
}

/** Evaluate cubic Bézier position at t ∈ [0,1]. */
export function bezierPoint(path: CubicBezierPath, t: number): Point {
  const u = 1 - t
  const tt = t * t
  const uu = u * u
  const uuu = uu * u
  const ttt = tt * t
  return {
    x: uuu * path.p0.x + 3 * uu * t * path.p1.x + 3 * u * tt * path.p2.x + ttt * path.p3.x,
    y: uuu * path.p0.y + 3 * uu * t * path.p1.y + 3 * u * tt * path.p2.y + ttt * path.p3.y,
  }
}

/** Write cubic Bézier position into `out` (no allocation). */
export function bezierPointInto(
  path: CubicBezierPath,
  t: number,
  out: Point,
): void {
  const u = 1 - t
  const tt = t * t
  const uu = u * u
  const uuu = uu * u
  const ttt = tt * t
  out.x = uuu * path.p0.x + 3 * uu * t * path.p1.x + 3 * u * tt * path.p2.x + ttt * path.p3.x
  out.y = uuu * path.p0.y + 3 * uu * t * path.p1.y + 3 * u * tt * path.p2.y + ttt * path.p3.y
}

/** First derivative of cubic Bézier (velocity direction). */
export function bezierDerivative(path: CubicBezierPath, t: number): Point {
  const u = 1 - t
  return {
    x:
      3 * u * u * (path.p1.x - path.p0.x) +
      6 * u * t * (path.p2.x - path.p1.x) +
      3 * t * t * (path.p3.x - path.p2.x),
    y:
      3 * u * u * (path.p1.y - path.p0.y) +
      6 * u * t * (path.p2.y - path.p1.y) +
      3 * t * t * (path.p3.y - path.p2.y),
  }
}

/**
 * Build a cubic Bézier from `from` → `to` with slightly randomized control
 * points so motion feels like a human hand rather than a straight line.
 */
export function createCurvedPath(
  from: Point,
  to: Point,
  random: () => number = Math.random,
): CubicBezierPath {
  const dx = to.x - from.x
  const dy = to.y - from.y
  const dist = Math.hypot(dx, dy) || 1
  const nx = -dy / dist
  const ny = dx / dist

  const jitterScale = dist * (0.15 + random() * 0.2)
  const side = random() < 0.5 ? -1 : 1
  const j1 = side * jitterScale * (0.6 + random() * 0.4)
  const j2 = side * jitterScale * (0.4 + random() * 0.5) * (random() < 0.5 ? -1 : 1)

  const t1 = 0.25 + random() * 0.15
  const t2 = 0.6 + random() * 0.2

  return {
    p0: { x: from.x, y: from.y },
    p1: {
      x: from.x + dx * t1 + nx * j1,
      y: from.y + dy * t1 + ny * j1,
    },
    p2: {
      x: from.x + dx * t2 + nx * j2,
      y: from.y + dy * t2 + ny * j2,
    },
    p3: { x: to.x, y: to.y },
  }
}

/** Duration in ms from distance, clamped. */
export function durationForDistance(
  dist: number,
  minDuration = 280,
  maxDuration = 900,
  pxPerMs = 1.1,
): number {
  return clamp(dist / pxPerMs, minDuration, maxDuration)
}

const sharedFrame: MotionFrame = {
  x: 0,
  y: 0,
  vx: 0,
  vy: 0,
  headingRad: 0,
  progress: 0,
}

export function samplePath(
  path: CubicBezierPath,
  t: number,
  progress: number,
  options: SamplePathOptions = {},
): MotionFrame {
  const out = options.out ?? sharedFrame
  const needHeading = options.needHeading !== false

  bezierPointInto(path, t, out)
  out.progress = progress

  if (needHeading) {
    const deriv = bezierDerivative(path, t)
    out.vx = deriv.x
    out.vy = deriv.y
    out.headingRad = Math.atan2(deriv.y, deriv.x)
  } else {
    out.vx = 0
    out.vy = 0
    out.headingRad = 0
  }

  return out
}

/**
 * Animate along a cubic path with rAF. Returns a cancelable handle.
 */
export function animateAlong(path: CubicBezierPath, options: AnimateAlongOptions): AnimateHandle {
  const ease = options.ease ?? easeInOutCubic
  const now = options.now ?? (() => performance.now())
  const raf = options.raf ?? ((cb) => requestAnimationFrame(cb))
  const caf = options.caf ?? ((id) => cancelAnimationFrame(id))
  const needHeading = options.needHeading !== false
  const frame = sharedFrame

  let cancelled = false
  let frameId = 0
  const start = now()

  let resolveFinished!: () => void
  const finished = new Promise<void>((resolve) => {
    resolveFinished = resolve
  })

  const tick = (time: number) => {
    if (cancelled) {
      resolveFinished()
      return
    }
    const elapsed = time - start
    const linear = options.duration <= 0 ? 1 : clamp(elapsed / options.duration, 0, 1)
    const eased = ease(linear)
    options.onFrame(samplePath(path, eased, linear, { needHeading, out: frame }))

    if (linear < 1) {
      frameId = raf(tick)
    } else {
      resolveFinished()
    }
  }

  // Seed first frame immediately at t=0
  options.onFrame(samplePath(path, 0, 0, { needHeading, out: frame }))
  frameId = raf(tick)

  return {
    cancel() {
      if (cancelled) return
      cancelled = true
      caf(frameId)
      resolveFinished()
    },
    finished,
  }
}

/** Instant jump (no animation). */
export function jumpTo(to: Point, onFrame: (frame: MotionFrame) => void): void {
  sharedFrame.x = to.x
  sharedFrame.y = to.y
  sharedFrame.vx = 0
  sharedFrame.vy = 0
  sharedFrame.headingRad = 0
  sharedFrame.progress = 1
  onFrame(sharedFrame)
}

export function useCursorMotion() {
  return {
    createCurvedPath,
    animateAlong,
    jumpTo,
    durationForDistance,
    samplePath,
    easeInOutCubic,
    distance,
    lerp,
  }
}

import { ref, type Ref } from 'vue'
import type { ClickOptions, CursorInteractionState, MouseButton } from '../types'

export interface UseCursorInteractionOptions {
  pressedScale?: number
  animationDuration?: number
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms))
}

function buttonCode(button: MouseButton): number {
  return button === 'right' ? 2 : 0
}

function buttonsMask(button: MouseButton): number {
  return button === 'right' ? 2 : 1
}

/**
 * Dispatch a synthetic pointer/mouse click sequence at viewport coordinates.
 * Browsers may still block some native behaviors (e.g. context menu).
 */
export function dispatchRealClick(
  clientX: number,
  clientY: number,
  button: MouseButton,
): void {
  const target = document.elementFromPoint(clientX, clientY)
  if (!target) {
    console.warn('vue-cursor: no element under hotspot for real click')
    return
  }

  const down: MouseEventInit = {
    bubbles: true,
    cancelable: true,
    clientX,
    clientY,
    button: buttonCode(button),
    buttons: buttonsMask(button),
  }

  if (typeof PointerEvent !== 'undefined') {
    const pointerDown: PointerEventInit = {
      ...down,
      pointerId: 1,
      pointerType: 'mouse',
      isPrimary: true,
    }
    target.dispatchEvent(new PointerEvent('pointerdown', pointerDown))
  }
  target.dispatchEvent(new MouseEvent('mousedown', down))

  const up: MouseEventInit = { ...down, buttons: 0 }
  if (typeof PointerEvent !== 'undefined') {
    target.dispatchEvent(
      new PointerEvent('pointerup', {
        ...up,
        pointerId: 1,
        pointerType: 'mouse',
        isPrimary: true,
      }),
    )
  }
  target.dispatchEvent(new MouseEvent('mouseup', up))

  if (button === 'left') {
    target.dispatchEvent(new MouseEvent('click', up))
  } else {
    target.dispatchEvent(new MouseEvent('contextmenu', up))
  }
}

export function useCursorInteraction(options: UseCursorInteractionOptions = {}) {
  const pressedScaleAmount = options.pressedScale ?? 0.9
  const defaultDuration = () => options.animationDuration ?? 120

  const state: Ref<CursorInteractionState> = ref('idle')
  const button: Ref<MouseButton | null> = ref(null)
  const pressScale: Ref<number> = ref(1)

  let pressToken = 0

  async function press(
    btn: MouseButton = 'left',
    delayMs = defaultDuration(),
  ): Promise<void> {
    const token = ++pressToken
    state.value = 'pressing'
    button.value = btn
    pressScale.value = pressedScaleAmount
    await sleep(Math.max(40, delayMs))
    if (token !== pressToken) return
    state.value = 'pressed'
  }

  async function release(): Promise<void> {
    pressToken += 1
    state.value = 'idle'
    button.value = null
    pressScale.value = 1
  }

  async function click(opts: ClickOptions & { clientX?: number; clientY?: number } = {}): Promise<void> {
    const btn = opts.button ?? 'left'
    const animate = opts.animate !== false
    const delayMs = opts.delayMs ?? defaultDuration()

    if (animate) {
      await press(btn, delayMs)
    } else {
      button.value = btn
      state.value = 'pressed'
    }

    if (opts.real && typeof opts.clientX === 'number' && typeof opts.clientY === 'number') {
      dispatchRealClick(opts.clientX, opts.clientY, btn)
    }

    await release()
  }

  return {
    state,
    button,
    pressScale,
    press,
    release,
    click,
  }
}

import type { Ref } from 'vue'
import type { MotionFrame, MotionStyle, Point } from '../types'

export interface UseCursorMotionStyleOptions {
  /**
   * Tip orientation at CSS rotate(0), as offset from pointing **up** (degrees).
   * Hand (finger up) = 0; arrow/pointer (tip up-left) ≈ -45.
   * May be a ref/getter so it tracks the active shape.
   */
  defaultAngle?: number | Ref<number> | (() => number)
  /** How quickly rotation chases the travel heading (0–1). */
  spring?: number
  /** Resting CSS rotation when idle (usually 0). */
  restDeg?: number
  /** Speed (px/frame-ish) below which follow motion settles upright. */
  settleSpeed?: number
  /** Called whenever rotation changes (for imperative paint). */
  onRotation?: (deg: number) => void
}

function radToDeg(rad: number): number {
  return (rad * 180) / Math.PI
}

/** Normalize to (-180, 180] so spring lerp takes the shortest turn. */
export function normalizeDeg(deg: number): number {
  return ((deg + 540) % 360) - 180
}

function lerpAngle(from: number, to: number, t: number): number {
  const diff = ((to - from + 540) % 360) - 180
  return from + diff * t
}

function resolveNumber(
  value: number | Ref<number> | (() => number) | undefined,
  fallback: number,
): number {
  if (value == null) return fallback
  if (typeof value === 'function') return value()
  if (typeof value === 'object' && 'value' in value) return value.value
  return value
}

/**
 * CSS rotation that aims the tip along `headingRad` (screen atan2: 0=east, 90=down).
 * `defaultAngle` is the tip’s offset from pointing up at rest.
 */
export function headingToRotation(
  headingRad: number,
  defaultAngle = 0,
): number {
  return normalizeDeg(radToDeg(headingRad) + 90 - defaultAngle)
}

/** @deprecated Use headingToRotation */
export function headingToTilt(
  headingRad: number,
  _maxTilt: number,
  defaultAngle = 0,
): number {
  return headingToRotation(headingRad, defaultAngle)
}

/**
 * `standard` keeps rotation at restDeg (0).
 * `dangling` rotates so the tip points along travel.
 * Rotation is a plain number (not a Vue ref) for the rAF hot path.
 */
export function useCursorMotionStyle(
  style: Ref<MotionStyle> | (() => MotionStyle),
  options: UseCursorMotionStyleOptions = {},
) {
  const spring = options.spring ?? 0.22
  const restDeg = options.restDeg ?? 0
  const settleSpeed = options.settleSpeed ?? 1.2

  let rotationDeg = restDeg
  let settling = false
  let travelHeadingRad: number | null = null
  let settleRaf = 0

  function getStyle(): MotionStyle {
    return typeof style === 'function' ? style() : style.value
  }

  function getDefaultAngle(): number {
    return resolveNumber(options.defaultAngle, 0)
  }

  function setRotation(deg: number): void {
    rotationDeg = deg
    options.onRotation?.(deg)
  }

  function cancelSettleLoop() {
    if (settleRaf) {
      cancelAnimationFrame(settleRaf)
      settleRaf = 0
    }
  }

  function angleError(from: number, to: number): number {
    return ((from - to + 540) % 360) - 180
  }

  function startSettleLoop(): void {
    if (getStyle() !== 'dangling') {
      setRotation(restDeg)
      travelHeadingRad = null
      settling = false
      return
    }
    settling = true
    travelHeadingRad = null
    cancelSettleLoop()

    const tick = () => {
      if (!settling || getStyle() !== 'dangling') {
        settleRaf = 0
        return
      }
      const next = lerpAngle(rotationDeg, restDeg, Math.min(1, spring * 1.6))
      setRotation(next)
      if (Math.abs(angleError(rotationDeg, restDeg)) < 0.4) {
        setRotation(restDeg)
        settling = false
        settleRaf = 0
        return
      }
      settleRaf = requestAnimationFrame(tick)
    }
    settleRaf = requestAnimationFrame(tick)
  }

  function beginTravel(from: Point, to: Point): void {
    cancelSettleLoop()
    settling = false
    const dx = to.x - from.x
    const dy = to.y - from.y
    if (Math.hypot(dx, dy) > 1) {
      travelHeadingRad = Math.atan2(dy, dx)
    } else {
      travelHeadingRad = null
    }
  }

  /** True when scripted travel heading is locked (caller can skip Bézier heading). */
  function hasLockedTravel(): boolean {
    return travelHeadingRad != null
  }

  function isSettled(): boolean {
    return !settling && Math.abs(angleError(rotationDeg, restDeg)) < 0.4
  }

  function chaseHeading(headingRad: number): void {
    const target = headingToRotation(headingRad, getDefaultAngle())
    setRotation(lerpAngle(rotationDeg, target, spring))
  }

  function onFrame(frame: MotionFrame): void {
    if (getStyle() !== 'dangling') {
      cancelSettleLoop()
      if (rotationDeg !== restDeg) setRotation(restDeg)
      settling = false
      travelHeadingRad = null
      return
    }

    if (travelHeadingRad != null) {
      if (frame.progress >= 0.97) {
        startSettleLoop()
        return
      }
      if (settling) cancelSettleLoop()
      settling = false
      chaseHeading(travelHeadingRad)
      return
    }

    const speed = Math.hypot(frame.vx, frame.vy)
    if (speed > settleSpeed) {
      if (settling) cancelSettleLoop()
      settling = false
      chaseHeading(Math.atan2(frame.vy, frame.vx))
      return
    }

    if (!settling && Math.abs(angleError(rotationDeg, restDeg)) > 0.4) {
      startSettleLoop()
    }
  }

  function onSettle(): void {
    startSettleLoop()
  }

  function reset(): void {
    cancelSettleLoop()
    setRotation(restDeg)
    settling = false
    travelHeadingRad = null
  }

  function getRotation(): number {
    return rotationDeg
  }

  return {
    getRotation,
    hasLockedTravel,
    isSettled,
    beginTravel,
    onFrame,
    onSettle,
    reset,
  }
}

import type { Point } from '../types'

export class TargetResolutionError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'TargetResolutionError'
  }
}

/**
 * Resolve a CSS selector or Element to the center of its bounding box
 * in viewport coordinates.
 */
export function resolveElementCenter(target: string | Element): Point {
  const el =
    typeof target === 'string' ? document.querySelector(target) : target

  if (!el) {
    const message =
      typeof target === 'string'
        ? `vue-cursor: no element matches selector "${target}"`
        : 'vue-cursor: target element is null'
    console.warn(message)
    throw new TargetResolutionError(message)
  }

  const rect = el.getBoundingClientRect()
  return {
    x: rect.left + rect.width / 2,
    y: rect.top + rect.height / 2,
  }
}

/**
 * Normalize move targets: numbers as coordinates, or selector/Element as center.
 */
export function resolveMoveTarget(
  target: number | string | Element,
  y?: number,
): Point {
  if (typeof target === 'number') {
    if (typeof y !== 'number' || Number.isNaN(y)) {
      throw new TargetResolutionError(
        'vue-cursor: moveTo(x, y) requires numeric y when x is a number',
      )
    }
    return { x: target, y }
  }
  return resolveElementCenter(target)
}

export type ShapeName = 'arrow' | 'pointer' | 'hand'

export type MotionStyle = 'standard' | 'dangling'

export type MouseButton = 'left' | 'right'

export type CursorInteractionState = 'idle' | 'pressing' | 'pressed'

export interface Point {
  x: number
  y: number
}

export interface MotionFrame extends Point {
  vx: number
  vy: number
  headingRad: number
  progress: number
}

export interface MoveToOptions {
  animate?: boolean
  duration?: number
}

export interface ClickOptions {
  button?: MouseButton
  real?: boolean
  animate?: boolean
  move?: boolean
  delayMs?: number
  /** Show the radiating-lines burst at the click point (default: component `clickBurst` prop). */
  burst?: boolean
}

export interface ClickBurstInstance {
  id: number
  x: number
  y: number
  color: string
}

export type MoveTarget = string | Element | Point
